INSERT INTO temp_import_pages VALUES ('{"pageId": "e0830000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 83, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "83", "printedPageNumber": 83, "pdfPageNumber": 466, "sequenceIndex": 73, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0830100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER—III", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0830200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "QUOTATIONS FROM HADITH", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0830300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—I", "sourceIdentifier": "I", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0830400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0830000-0000-4000-8000-000000000001", "structuralNodeId": "b0830100-0000-4000-8000-000000000001", "sequenceIndex": 0, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830100-0000-4000-8000-000000000001", "structuralNodeId": "b0830200-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "QUOTATIONS FROM HADITH", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830200-0000-4000-8000-000000000001", "structuralNodeId": "b0830300-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830300-0000-4000-8000-000000000001", "structuralNodeId": "b0830300-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عمار بن ياسر رضي الله عنه قال سمعت رسول الله ﷺ يقول إن الرجل لينصرف وما كتب له إلا عشر صلاته تسعها ثمنها سبعها سدسها خمسها ربعها ثلثها نصفها رواه أبو داود والنسائي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830400-0000-4000-8000-000000000001", "structuralNodeId": "b0830300-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Ammar bin Yaasir (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"When a person finishes his salaat, he gets one tenth, one ninth, one eighth, one seventh, one sixth, one fifth, one fourth, one third or one half of the maximum reward (according to the quality of salaat performed by him).\"\n\nThis shows that the reward is given in proportion to the sincerity and devotion with which salaat is performed. So much so, that some get only one tenth of the total reward. There are others who get a reward ranging from one tenth to one half of the maximum. It is also correct to say that there are some who receive the reward in full and there are others who get no reward at all.\n\nIt is stated in a hadith that Allah has a standard for fardh salaat. An account is kept of the measure by which a salaat falls short of that standard.\n\nIt is said in the hadith that devotion in salaat will be the first thing to be taken away from the world. A time will come when not a single person in the whole congregation will offer his salaat with proper devotion.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830500-0000-4000-8000-000000000001", "structuralNodeId": "b0830400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830600-0000-4000-8000-000000000001", "structuralNodeId": "b0830400-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رُوِيَ عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ ﷺ فَمَنْ صَلَّى الصَّلَاةَ لِوَقْتِهَا وَأَسْبَغَ لَهَا وُضُوءَهَا وَأَتَمَّ لَهَا قِيَامَهَا وَخُشُوعَهَا وَرُكُوعَهَا وَسُجُودَهَا خَرَجَتْ وَهِيَ بَيْضَاءُ مُسْفِرَةٌ تَقُولُ حَفِظَكَ اللَّهُ كَمَا حَفِظْتَنِي مَنْ صَلَّاهَا لِغَيْرِ وَقْتِهَا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0840000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 84, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "84", "printedPageNumber": 84, "pdfPageNumber": 467, "sequenceIndex": 74, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0840000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَلَمْ يُسْبِغْ لَهَا وُضُوءَهَا وَلَمْ يُتِمَّ لَهَا خُشُوعَهَا وَلَا رُكُوعَهَا وَلَا سُجُودَهَا خَرَجَتْ وَهِيَ سَوْدَاءُ مُظْلِمَةٌ تَقُولُ ضَيَّعَكَ اللَّهُ كَمَا ضَيَّعْتَنِي حَتَّى إِذَا كَانَتْ حَيْثُ شَاءَ اللَّهُ لُفَّتْ كَمَا يُلَفُّ الثَّوْبُ الْخَلِقُ ثُمَّ ضُرِبَ بِهَا وَجْهُهُ رَوَاهُ الطَّبَرَانِي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 84"}, {"id": "f0840100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 84"}, {"id": "f0840200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas (Radhiyallaho anho) narrates that he heard the Holy Prophet (Sallallaho alaihe wasallam) saying, \"When a person offers his salaat at its fixed hours with proper wudhu, with humility and submission and with qiyaam, ruku and sajdah done satisfactorily, then such a salaat rises up in a bright and beautiful form and blesses the person in words: ''May Allah guard you as you have guarded me.'' On the other hand, if a person is not punctual with his salaat nor does he perform wudhu, qiyaam, ruku and sajdah properly, then salaat rises up in an ugly and dark shape and curses the person saying, ''May Allah ruin you as you have ruined me!'' Then it is flung back like a dirty rag at the face of the person.\"\n\nLucky are those whose salaat is so perfect in all respects that this most important worship of Allah would pray for them. But what to say about the salaat which most of the people are wont? They go into sajdah direct from ruku, and they hardly lift their head from the first sajdah when they go for the second like a crow pecking at something. The curse that such a person deserves is mentioned in this hadith. When the salaat is cursing us then what else can check our downfall? This is why the condition of the Muslims is deteriorating day by day in every nook and corner of the world.\n\nThe same description is given in another hadith, with the addition that a salaat offered by a person with sincerity and devotion rises up highly illuminated, the gates of Heaven are let open for its reception, and then it intercedes (before Allah) for His devotee.\n\nThe Prophet (Sallallaho alaihe wasallam) has said, \"The likeness of a person not bowing fully in ruku is that of a pregnant woman aborting just before delivery.\"\n\nIn a hadith, it is stated, \"There are many fasting persons who get nothing out of their fast except hunger and thirst, and there are many worshippers who keep a vigil but get nothing from their vigil except sleeplessness.\"\n\nHadhrat Aa''ishah (Radhiyallaho anha) narrates that", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 84"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0850000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 85, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "85", "printedPageNumber": 85, "pdfPageNumber": 468, "sequenceIndex": 75, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0850100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—III", "sourceIdentifier": "III", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0850000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}, {"id": "f0850100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "she heard the Prophet (Sallallaho alaihe wasallam) saying, \"Allah has decided to save (from punishment of the Hereafter) a person coming before Him who has been offering salaat five times daily at its fixed hours, with due sincerity and devotion and with proper wudhu. As regards a person who does not so come before Allah, there is no guarantee for him. He may be forgiven by Allah''s special Grace or taken to task.\n\nOnce the Prophet (Sallallaho alaihe wasallam) came to his companions and said, \"Do you know what Allah has said?\" The companions replied, \"Allah and His Apostle know best.\" He repeated the question twice and the companions made the same reply each time. Then he said, \"Allah says, ''By my Greatness and My Glory, I must bring into Paradise the person offering salaat five times daily at its fixed hours. As regards the person who does not ensure his salaat, I may forgive him by My mercy or take him to task.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}, {"id": "f0850200-0000-4000-8000-000000000001", "structuralNodeId": "b0850100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}, {"id": "f0850300-0000-4000-8000-000000000001", "structuralNodeId": "b0850100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال سمعت رسول الله ﷺ يقول إن أول ما يحاسب به العبد يوم القيامة من عمله صلاته فإن صلحت فقد أفلح وأنجح وإن فسدت فقد خاب وخسر وإن انتقص من فريضته قال الرب انظروا هل لعبدي من تطوع فيكمل بها ما انتقص من الفريضة ثم يكون سائر عمله على ذلك", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}, {"id": "f0850400-0000-4000-8000-000000000001", "structuralNodeId": "b0850100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates, \"We heard the Prophet (Sallallaho alaihe wasallam) saying, ''The first among the doings of a person to be reckoned for on the Day of Judgement shall be his salaat. A person will succeed and attain his goal if his salaat is accepted, and he will fail and lose badly if it is rejected. If any deficiency is found in his fardh salaat, Allah will say (to the Angels): \"Look for any nafl salaat in his account\". Then the deficiency in his fardh salaat will be made good by nafl salaat. The rest of the religious practices (viz. Fast, Zakaat etc.) will then be reckoned for in the same manner.''\n\nThis hadith shows that we should have adequate nafl salaat to our credit to make up any deficiency in our fardh salaat. It is a habit with many people to say, \"It is enough to observe only the fardh salaat. nafl salaat is meant for the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;